import React, { useEffect, useState, useCallback } from 'react';
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid, ResponsiveContainer,
  PieChart, Pie, Cell, Legend
} from 'recharts';

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#A28DFF', '#FF7C7C'];

function StatisticsViewer() {
  const [questions, setQuestions] = useState([]);
  const [selectedId, setSelectedId] = useState('');
  const [data, setData] = useState([]);
  const [questionText, setQuestionText] = useState('');
  const [chartType, setChartType] = useState('bar');

  const fetchStatistics = useCallback((questionId) => {
    fetch(`http://localhost:3001/api/statistics/choices/${questionId}`)
      .then(res => res.json())
      .then(statisticsData => {
        console.log('Полученные данные для статистики:', statisticsData);
        const transformedData = statisticsData.map(item => ({
          choice_text: item.choice_text || 'Неизвестно',
          count: Number(item.count) || 0
        }));
        console.log('Преобразованные данные:', transformedData);
        setData(transformedData);
      })
      .catch(error => {
        console.error('Ошибка при получении статистики:', error);
        setData([]);
      });
  }, []);

  useEffect(() => {
    fetch('http://localhost:3001/api/questions')
      .then(res => res.json())
      .then(data => {
        console.log('Полученные вопросы:', data);
        setQuestions(data);
        if (selectedId) {
          fetchStatistics(selectedId);
        }
      })
      .catch(error => {
        console.error('Ошибка при получении вопросов:', error);
      });
  }, [selectedId, fetchStatistics]);

  useEffect(() => {
    if (selectedId && questions.length > 0) {
      const question = questions.find(q => q.id.toString() === selectedId);
      setQuestionText(question ? question.question_text : '');
    }
  }, [selectedId, questions]);

  return (
    <div style={{ padding: '2rem' }}>
      <h2>Статистика по вопросам</h2>
      <div style={{ marginBottom: '1rem' }}>
        <select
          value={selectedId}
          onChange={(e) => setSelectedId(e.target.value)}
        >
          <option value="">-- Выберите вопрос --</option>
          {questions
            .filter(q => q.is_choice_based || q.question_text.includes("Оцените"))
            .map(q => (
              <option key={q.id} value={q.id}>
                {q.id} — {q.question_text}
              </option>
            ))}
        </select>
        <select
          value={chartType}
          onChange={(e) => setChartType(e.target.value)}
          style={{ marginLeft: '10px' }}
        >
          <option value="bar">Столбчатая диаграмма</option>
          <option value="pie">Круговая диаграмма</option>
        </select>
      </div>
      {console.log('Данные для графика:', data)}
      {data.length > 0 ? (
        <>
          <h3>{questionText}</h3>
          <ResponsiveContainer width="100%" height={400}>
            {chartType === 'bar' ? (
              <BarChart data={data} margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="choice_text" label={{ value: 'Ответ', position: 'insideBottom', offset: -5 }} />
                <YAxis />
                <Tooltip />
                <Bar dataKey="count" fill="#82ca9d" />
              </BarChart>
            ) : (
              <PieChart>
                <Pie
                  data={data}
                  dataKey="count"
                  nameKey="choice_text"
                  cx="50%"
                  cy="50%"
                  outerRadius={120}
                  label
                >
                  {data.map((_, i) => (
                    <Cell key={i} fill={COLORS[i % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            )}
          </ResponsiveContainer>
        </>
      ) : selectedId ? (
        <p>Нет данных для отображения или count = 0</p>
      ) : null}
    </div>
  );
}

export default StatisticsViewer;
